import java.util.*;
import java.io.*;

public class Main {
    static long[][] countUnique(long[][] records) {
        // Write your solution here
        // return rows {employeeId, count} sorted by employeeId
        return new long[0][];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int m = (int) in.nval;
        long[][] records = new long[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); records[i][0] = (long) in.nval;
            in.nextToken(); records[i][1] = (long) in.nval;
        }
        StringBuilder sb = new StringBuilder();
        for (long[] row : countUnique(records)) sb.append(row[0]).append(' ').append(row[1]).append('\n');
        System.out.print(sb);
    }
}
